from decimal import Decimal

from .money import MAX_AMOUNT, _CTX, parse_amount, format_amount


def make_invoice(amounts):
    if not isinstance(amounts, (list, tuple)):
        raise ValueError("amounts must be a list")
    total = Decimal("0.00")
    for item in amounts:
        total = _CTX.add(total, parse_amount(item))
    if total > MAX_AMOUNT:
        raise ValueError("total too large")
    return {"total": format_amount(total), "count": len(amounts)}
